  &reftitle.parameters;




     arrays


Recursively merge गरिने arrays को variable list।

&reftitle.changelog;







     &Version;
     &Description;





     7.4.0
     यो function अब कुनै पनि parameter बिना call गर्न सकिन्छ। पहिले, कम्तीमा एउटा parameter आवश्यक पर्थ्यो।

  &reftitle.examples;



    array_merge_recursive को उदाहरण


<?php
$ar1 = array("color" => array("favorite" => "red"), 5);
$ar2 = array(10, "color" => array("favorite" => "green", "blue"));
$result = array_merge_recursive($ar1, $ar2);
print_r($result);
?>


    &example.outputs;


Array
(
    [color] => Array
        (
            [favorite] => Array
                (
                    [0] => red
                    [1] => green
                )

            [0] => blue
        )

    [0] => 5
    [1] => 10
)
